ddl:
CREATE TABLE Exam (
    Exam_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    Time DATETIME
);

CREATE TABLE Student (
    Name VARCHAR(255),
    Student_ID INTEGER PRIMARY KEY
);

CREATE TABLE Practice_Question (
    Exam_ID_it_belongs_to INTEGER NOT NULL,
    Question_Content VARCHAR(255),
    Question_ID INTEGER PRIMARY KEY,
    Score FLOAT,
    FOREIGN KEY (Exam_ID_it_belongs_to) REFERENCES Exam(Exam_ID)
);

CREATE TABLE Submission_Record (
    Exam_ID INTEGER NOT NULL,
    Student_ID INTEGER NOT NULL,
    Submission_ID INTEGER PRIMARY KEY,
    Submission_Status VARCHAR(255),
    FOREIGN KEY (Exam_ID) REFERENCES Exam(Exam_ID),
    FOREIGN KEY (Student_ID) REFERENCES Student(Student_ID)
);

CREATE TABLE Answer_Record (
    Answer_Content VARCHAR(255),
    Answer_Record_ID INTEGER PRIMARY KEY,
    Practice_Question_ID_it_belongs_to INTEGER NOT NULL,
    Submission_ID_it_belongs_to INTEGER NOT NULL,
    FOREIGN KEY (Practice_Question_ID_it_belongs_to) REFERENCES Practice_Question(Question_ID),
    FOREIGN KEY (Submission_ID_it_belongs_to) REFERENCES Submission_Record(Submission_ID)
);
